import pytest

import jwt_lite


def test_sv5sec02_compositional():
    import base64, hashlib, hmac, json
    b = lambda o: base64.urlsafe_b64encode(json.dumps(o).encode()).rstrip(b'=').decode()
    mk = lambda h, p, key: b(h) + '.' + b(p) + '.' + base64.urlsafe_b64encode(hmac.new(key, (b(h) + '.' + b(p)).encode(), hashlib.sha256).digest()).rstrip(b'=').decode()
    v = jwt_lite.verify
    t = mk({'alg': 'HS256', 'kid': 'k2'}, {'sub': 'ann', 'exp': 100, 'aud': ['web', 'api']}, b'two')
    assert v(t, {'k1': 'one', 'k2': 'two'}, now=99, audience='api') == {'sub': 'ann', 'exp': 100, 'aud': ['web', 'api']}
    assert v(mk({'alg': 'HS256'}, {'n': 1}, b's'), {'only': b's'}, now=0) == {'n': 1}
